        for dc in range(-W,W+1):
            s={(r+dr,cc+dc) for r,cc in pts}
            if all(0<=r<H and 0<=cc<W for r,cc in s):
                out.append((abs(dr)+abs(dc),dr,dc))
    return sorted(out)

def search(Ai,Bo):
    vals,cnts=np.unique(Ai,return_counts=True); bg=int(vals[np.argmax(cnts)])
    H,W=Bo.shape
    cols=[int(v) for v in np.unique(Ai) if v!=bg]
    opt={c:options(Ai,c,H,W) for c in cols}
    target=set(map(tuple,np.argwhere(Bo!=bg)))
    # exact cover: choose one shift per color, disjoint, union==target
    order=sorted(cols,key=lambda c:-len(opt[c]))
    sols=[]; best=None
    def bt(i,sol_,used):
        nonlocal sols,best
        if best is not None and len(sols)>best[0]: return
        if i==len(order):
            if used==target:
                sols.append(dict(sol_)); 
                if len(sols)==1: best=(0,None)
            return
        c=order[i]; cpts=[tuple(p_) for p_ in np.argwhere(Ai==c)]
        for k,(m,dr,dc) in enumerate(opt[c]):
            s={(r+dr,cc+dc) for r,cc in cpts}
            if s & used or not (s & target): continue
            # prune
            rem=len(target)-len(used)-len(s)
            if rem < 0: continue
            if rem > sum(len([q for q in []]) for oc in order[i+1:]): pass
            # tighter prune: remaining cells must be <= sum of remaining shape sizes
            if rem > sum(len(np.argwhere(Ai==oc)) for oc in order[i+1:]): continue
            sol_[c]=(dr,dc)
            bt(i+1,sol_,used|s)
            del sol_[c]
            if len(sols)>1: return  # stop after finding solutions
    bt(0,{})
    return sols[:5]

