def f(A):
    vals,cnts=np.unique(A,return_counts=True); bg=int(vals[np.argmax(cnts)])
    H,W=A.shape; canvas=np.full((H,W),bg,int)
    for c in [int(v) for v in np.unique(A) if v!=bg]:
        pts=[tuple(p_) for p_ in np.argwhere(A==c)]
        r0=min(r for r,cc in pts); c0=min(cc for r,cc in pts)
        for r,cc in pts:
            q=(r-r0, cc-c0)
            if 0<=q[0]<H and 0<=q[1]<W: canvas[q]=c
    rs,cs=np.where(canvas!=bg)
    rmin,rmax=rs.min(),rs.max(); cmin,cmax=cs.min(),cs.max()
    return canvas[rmin:rmax+1, cmin:cmax+1].tolist()

