# Exact cover: choose shift per color s.t. shifted cells subset of frame & union==output painted cells, disjoint across colors.
def shifts(A,c,H,W):
    pts=[tuple(p) for p in np.argwhere(A==c)]
    out=[]
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            s={(r+dr,cc+dc) for r,cc in pts}
            if s<= {(r,cc) for r in range(H) for cc in range(W)}:
                out.append((dr,dc))
    return out
def solve(Ai,Bo,limit=5):
    vals,cnts=np.unique(Ai,return_counts=True); bg=int(vals[np.argmax(cnts)])
    H,W=Bo.shape
    cols=[int(v) for v in np.unique(Ai) if v!=bg]
    opt={c:shifts(Ai,c,H,W) for c in cols}
    target=set(map(tuple,np.argwhere(Bo!=bg)))
    sols=[]
    def bt(i,sol_,used):
        if len(sols)>=limit: return
        if i==len(cols):
            if used==target: sols.append(dict(sol_))
            return
        c=cols[i]; cand=opt[c]
        for k,(dr,dc) in enumerate(cand):
            s={(r+dr,cc+dc) for r,cc in [(r_,cc_) for r_,cc_ in np.argwhere(Ai==c)]}
            if s & used or not (s & target): continue
            if len(used|s)+sum(len(np.argwhere(Ai==oc)) for oc in cols[i+1:]) < len(target): continue
            sol_=sol_|{(k):(dr,dc)}
            # careful: dict key issue -> use order list
            bt(i+1,{},{}) 
        else:
            pass
    # redo properly
    sols=[]
    def bt2(idx,sol_dict,used):
        if len(sols)>=limit: return
        if idx==len(cols):
            if used==target: sols.append(dict(sol_dict))
            return
        c=cols[idx]; cand=opt[c]
        for dr,dc in cand:
            s={(r+dr,cc+dc) for r,cc in np.argwhere(Ai==c)}
            if s & used or not (s & target): continue
            bt2(idx+1,{**sol_dict,c:(dr,dc)},used|s)
    bt2(0,{},set())
    return sols
print('d1:',len(solve(A1,B1))); print(solve(A1,B1)[:1] if solve(A1,B1) else None)
